#!/usr/bin/env sh
# fetch Municipio~De~Hormigueros~Pr~Us (US) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://www.municipiohormiguerospr.com/_files/archives/37d3b3_b84467350f334c69b093e1ee0b8d6a22.zip?dn=Hormigueros_PR_GTFS.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
